const input = $input.first().json;
const headers = input.headers ?? {};
const body = input.body ?? {};
const authorization = headers.authorization ?? headers.Authorization;
if (!authorization?.startsWith('Bearer ')) throw new Error('A valid Quantura Bearer token is required.');
if (!body.dataset_id) throw new Error('dataset_id is required.');
if (!String(body.prompt ?? '').trim()) throw new Error('prompt is required.');
const variant = Math.max(0, Math.min(99, Number(body.variant ?? 0) || 0));
return [{ json: { authorization, dataset_id: String(body.dataset_id), prompt: String(body.prompt).trim().slice(0, 2000), selected_visual_id: body.selected_visual_id ? String(body.selected_visual_id) : null, variant } }];

const dashboard = $input.first().json;
const request = $('Validate Visual Request').first().json;
const prompt = request.prompt.toLowerCase();
const supported = ['area','line','bar','horizontal_bar','donut','scatter','radar','heatmap'];
const aliases = { pie: 'donut', column: 'bar', horizontal: 'horizontal_bar' };
let chartType = supported.find(type => prompt.includes(type.replace('_',' '))) ?? Object.keys(aliases).find(key => prompt.includes(key));
chartType = aliases[chartType] ?? chartType ?? null;
let action = 'recommend_dashboard';
if (prompt.includes('remove') || prompt.includes('delete')) action = 'remove_visual';
else if (prompt.includes('move') || prompt.includes('top') || prompt.includes('bottom') || prompt.includes('beside')) action = 'move_visual';
else if (chartType && request.selected_visual_id) action = 'change_chart_type';
else if (prompt.includes('rebuild') || prompt.includes('another') || prompt.includes('new dashboard')) action = 'replace_dashboard';
const selected = dashboard.visuals?.find(v => v.id === request.selected_visual_id) ?? null;
const patch = { action, visual_id: request.selected_visual_id, chart_type: chartType, position: prompt.includes('top') ? 'top' : prompt.includes('bottom') ? 'bottom' : null };
const warnings = [];
if (['remove_visual','move_visual','change_chart_type'].includes(action) && !selected) warnings.push('Select a dashboard visual before applying this instruction.');
return [{ json: { agent_name: 'Quantura Visual Agent', dataset_id: dashboard.dataset_id, version_id: dashboard.version_id, prompt: request.prompt, requested_patch: patch, selected_visual: selected, preview_only: true, dashboard, recommendations: dashboard.recommendations ?? [], insights: dashboard.insights ?? [], warnings, requires_frontend_apply: true, message: warnings.length ? warnings[0] : 'A validated dashboard preview and visual instruction are ready. Apply or reject the change in Quantura.' } }];
